import csv
from collections import defaultdict

data = defaultdict(list)
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        try:
            data[row['timeseries_id']].append((row['timestamp'], float(row['value'])))
        except ValueError:
            pass

zone_temps = {
    'F2_Z01_core_bottom': 'baef86cb-2941-5d61-87b0-ffa91d79f23a',
    'F3_Z01_core_mid':   'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
    'F4_Z01_core_top':   '14a08406-79a0-52ca-b8a1-8563259dc820',
}
zone_sp = {
    'F2_Z01': '1213f3a8-c23d-55b5-8187-4712d49a82ae',   # Cool SP
    'F3_Z01': '5b98cbc1-fd25-5d8c-a96e-c3de49819174',
    'F4_Z01': '22de734e-0a64-57ec-a6a5-f288ee06f947',
}

def is_occ(ts):
    # 8am to 5pm = hours 8..17
    h = int(ts[11:13])
    return 8 <= h <= 17

for name, ts in zone_temps.items():
    rows = data.get(ts, [])
    before = [v for t,v in rows if t.startswith('2018-06') and t < '2018-06-15' and is_occ(t)]
    after  = [v for t,v in rows if '2018-06-15' <= t < '2018-06-30' and is_occ(t)]
    print(f"{name}  rows total={len(rows)}  jun_occ_before={len(before)}  jun_occ_after={len(after)}")
    if before: print(f"   before mean = {sum(before)/len(before):.3f} C")
    if after:  print(f"   after  mean = {sum(after)/len(after):.3f} C")

